async fn detect_and_emit_events(&mut self) {
    let cur = self.op.get_current_leader();
    if cur != self.last_leader {
        if let Some((pid, accepted)) = cur {
            let _ = self
                .event_tx
                .send(OmniPaxosEvent::LeaderElected { pid, accepted })
                .await;
        }
        self.last_leader = cur;
    }
    let d = self.op.get_decided_idx();
    if d > self.last_decided_idx {
        let _ = self
            .event_tx
            .send(OmniPaxosEvent::Decided { new_decided_idx: d })
            .await;
        self.last_decided_idx = d;
    }
    if !self.last_reconfigured {
        if let Some(_ss) = self.op.is_reconfigured() {
            let _ = self
                .event_tx
                .send(OmniPaxosEvent::Reconfigured {
                    stop_sign_idx: self.op.get_decided_idx(),
                })
                .await;
            self.last_reconfigured = true;
        }
    }
}

pub(crate) async fn run<T, B, R>(mut state: ActorState<T, B>, _rt: PhantomData<fn() -> R>)
where
    T: ActorEntry,
    B: Storage<T> + Send + 'static,
    R: AsyncRuntime,
{
    let mut tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
    let mut egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();

    // async_channel::Receiver is !Unpin; keep it in a Pin<Box<...>> so the Stream
    // impl works under select_biased!.
    let cmd_rx = std::mem::replace(&mut state.cmd_rx, async_channel::bounded(1).1);
    let incoming_rx = std::mem::replace(&mut state.incoming_rx, async_channel::bounded(1).1);
    let mut cmd_rx = Box::pin(cmd_rx);
    let mut incoming_rx = Box::pin(incoming_rx);

    loop {
        select_biased! {
            _ = tick_fut => {
                state.op.tick();
                state.detect_and_emit_events().await;
                state.try_dispatch_undispatched();
                state.reconcile_unconfirmed();
                state.drain_notifiers();
                state.push_to_all_subs();
                tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
            }
            _ = egress_fut => {
                state.flush_outgoing();
                egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();
            }
            in_msg = incoming_rx.next() => {
                match in_msg {
                    Some(Message::AsyncRuntime(arm)) => state.handle_runtime_msg(arm),
                    Some(m) => state.handle_incoming_tracked(m),
                    None => break,
                }
            }
            cmd = cmd_rx.next() => {
                match cmd {
                    Some(c) => state.handle_command(c).await,
                    None => break,
                }
            }
        }
    }
}

/// Non-blocking drain of `outgoing_buf` onto `outgoing_tx`. Uses `try_send`
/// so a merely-full channel (slow consumer) doesn't block the actor loop;
/// unsent messages stay in `outgoing_buf` (in order) for the next attempt.
/// If the buffer exceeds [`Self::outgoing_buf_cap`], oldest messages are
/// dropped — see [`RuntimeConfig::max_outgoing_buffered`].
fn drain_outgoing_buf(&mut self) {
    let cap = self.outgoing_buf_cap();
    trim_oldest(&mut self.outgoing_buf, cap);

    let pending = std::mem::take(&mut self.outgoing_buf);
    let mut iter = pending.into_iter();
    for msg in iter.by_ref() {
        match self.outgoing_tx.try_send(msg) {
            Ok(()) => {}
            Err(async_channel::TrySendError::Full(msg)) => {
                self.outgoing_buf.push(msg);
                break;
            }
            Err(async_channel::TrySendError::Closed(_)) => {
                // Receiver dropped — user is not draining outgoing. Discard
                // everything remaining; nothing left to retry against.
                return;
            }
        }
    }
    self.outgoing_buf.extend(iter);
}

/// Enqueue one outgoing message without awaiting. Appends behind any
/// already-buffered messages (preserves order), then tries to drain.
/// Used for both core protocol traffic (via [`Self::flush_outgoing`]) and
/// runtime control-plane messages (`TaggedProposal` / `Assigned`).
fn enqueue_outgoing(&mut self, msg: Message<T>) {
    self.outgoing_buf.push(msg);
    self.drain_outgoing_buf();
}

/// Pull newly-produced OmniPaxos/BLE messages into `outgoing_buf` and drain.
fn flush_outgoing(&mut self) {
    self.op.take_outgoing_messages(&mut self.outgoing_buf);
    self.drain_outgoing_buf();
}

/// Push newly-decided entries to every subscriber, reading the log suffix
/// **once** and fanning out. Each sub keeps its own cursor, so slow subs
/// don't block fast ones; the storage read is amortized across all subs
/// starting from the trailing sub's position.
fn push_to_all_subs(&mut self) {
    if self.decided_subscribers.is_empty() {
        return;
    }
    let cur = self.op.get_decided_idx();
    let min_next = self
        .decided_subscribers
        .iter()
        .map(|s| s.next_idx)
        .min()
        .expect("non-empty checked above");
    if min_next >= cur {
        return;
    }
    // Read once, from the trailing sub's position. `entries[i]` is the log
    // entry at position `min_next + i`.
    let Some(entries) = self.op.read_decided_suffix(min_next) else {
        return;
    };
    // Fan out; drop closed subscribers in place via retain_mut.
    self.decided_subscribers.retain_mut(|sub| {
        // sub.next_idx should always be >= min_next; guard defensively.
        let start = sub.next_idx.saturating_sub(min_next);
        for entry in entries.iter().skip(start) {
            match sub.tx.try_send(entry.clone()) {
                Ok(()) => sub.next_idx += 1,
                Err(async_channel::TrySendError::Full(_)) => break,
                Err(async_channel::TrySendError::Closed(_)) => return false,
            }
        }
        true
    });
}

/// Subscribe to state-transition events. Each event is delivered to exactly one
/// receiver: if you clone the returned receiver, the clones share the queue.
/// For fan-out to multiple independent subscribers, wrap in a broadcasting task.
pub fn subscribe_events(&self) -> async_channel::Receiver<OmniPaxosEvent> {
    self.events_rx.clone()
}

impl Default for RuntimeConfig {
    fn default() -> Self {
        Self {
            tick_period: Duration::from_millis(10),
            egress_period: Duration::from_millis(1),
            cmd_channel_capacity: 1024,
            outgoing_capacity: 10_000,
            incoming_capacity: 10_000,
            event_capacity: 1024,
            append_notify_timeout: Duration::from_secs(5),
            decided_channel_capacity: 1024,
            max_pending_appends: 1024,
            max_decided_subscribers: 128,
            max_outgoing_buffered: 10_000,
        }
    }

/// Deliver an incoming message from the network to the actor.
pub async fn handle_incoming(&self, m: Message<T>) {
    let _ = self.incoming_tx.send(m).await;
}

/// it's closed. Since this runs on the single actor loop, that blocked
/// tick/election/command processing for the node entirely, not just delayed
/// egress. Uses a tiny `outgoing_capacity` and never drains it, so it fills
/// up almost immediately (the node has configured peers and sends BLE
/// heartbeats regardless of whether anyone's listening).
///
/// Notify-path (`TaggedProposal` / `Assigned`) backpressure is covered by
/// [`notify_egress_does_not_stall_when_outgoing_full`].
#[tokio::test]
async fn full_outgoing_channel_does_not_stall_actor_loop() {
    let nodes: Vec<NodeId> = vec![1, 2, 3];
    let cfg = RuntimeConfig {
        tick_period: Duration::from_millis(2),
        egress_period: Duration::from_millis(1),
        outgoing_capacity: 2,
        ..Default::default()
    };
    let op = build_op(1, nodes);
    let h = spawn_actor::<TestEntry, MemoryStorage<TestEntry>, TokioRuntime>(op, cfg);

    // Let the outgoing channel fill up completely without ever draining it.
    tokio::time::sleep(Duration::from_millis(100)).await;

    // The actor loop must still be responsive to commands -- if
    // flush_outgoing blocked on a full channel, this would hang.
    let idx = timeout(Duration::from_millis(500), h.decided_idx())
        .await
        .expect("actor loop appears stalled with a full outgoing channel");
    assert_eq!(idx, 0);

    // Draining now should still deliver messages (not silently and
    // permanently lost) once the consumer catches up.
    let out = h.outgoing_messages();
    timeout(Duration::from_secs(2), out.recv())
        .await
        .expect("no message ever arrived once draining resumed")
        .expect("outgoing channel closed unexpectedly");
}

/// Like `spawn_cluster`, but each node's outgoing drain can be paused via the
/// returned per-pid flags. While a node's flag is `true`, its drain task stops
/// calling `recv`, so that node's bounded `outgoing_messages` channel fills
/// and further egress hits backpressure -- without tearing down the rest of

fn drain_notifiers(&mut self) {
    let decided = self.op.get_decided_idx();
    let now = Instant::now();
    let cur_ballot = self.op.get_promise();
    let old = std::mem::take(&mut self.pending);
    for p in old {
        match p.assigned {
            Some((idx, _)) if idx <= decided => {
                let _ = p.reply.send(Ok(idx));
            }
            Some((idx, ballot)) if ballot < cur_ballot => {
                let _ = p
                    .reply
                    .send(Err(AppendError::Superseded { log_entry_idx: idx }));
            }
            _ if now > p.deadline => {
                let _ = p.reply.send(Err(AppendError::Timeout));
            }
            _ => self.pending.push_back(p),
        }
    }
}

/// Append an entry and await its decided log index.
///
/// Works from any node: the actor tags the entry with a unique id, routes it to
/// the current leader, and resolves the future when the assigned log index is
/// decided. If no leader is known yet, the call waits rather than failing fast --
/// it resolves once a leader is elected, or with `Timeout` if none is elected in
/// time. Fails with:
/// - [`AppendError::Timeout`] if the entry is not decided within
///   [`RuntimeConfig::append_notify_timeout`] (including when no leader was ever
///   elected in that time);
/// - [`AppendError::Propose`] if the underlying propose call itself failed (e.g. a
///   reconfiguration is already pending) -- only when this node owns the pending
///   call, otherwise it still resolves via `Timeout`;
/// - [`AppendError::Superseded`] if a leader change occurred before decision --
///   a heuristic, not a certainty; see its doc comment for why, and check the
///   returned index yourself if you need to know for sure;
/// - [`AppendError::TooManyOutstanding`] if [`RuntimeConfig::max_pending_appends`]
///   outstanding calls are already queued.
///
/// Uses [`RuntimeConfig::append_notify_timeout`] as the deadline; use
/// [`Self::append_notify_with_timeout`] to override it for a single call.
pub async fn append_notify(&self, entry: T) -> Result<usize, AppendError<T>> {
    self.append_notify_inner(entry, None).await
}

pub fn spawn_actor<T, B, R>(op: OmniPaxos<T, B>, cfg: RuntimeConfig) -> OmniPaxosHandle<T>
where
    T: ActorEntry,
    B: Storage<T> + Send + 'static,
    R: AsyncRuntime,
{
    let (cmd_tx, cmd_rx) = async_channel::bounded(cfg.cmd_channel_capacity);
    let (outgoing_tx, outgoing_rx) = async_channel::bounded(cfg.outgoing_capacity);
    let (incoming_tx, incoming_rx) = async_channel::bounded(cfg.incoming_capacity);
    let (event_tx, events_rx) = async_channel::bounded(cfg.event_capacity);

    let state = ActorState::new(
        op,
        cmd_rx,
        incoming_rx,
        outgoing_tx,
        event_tx,
        ActorConfig::from(&cfg),
    );

    R::spawn(run::<T, B, R>(state, PhantomData::<fn() -> R>));

    OmniPaxosHandle {
        cmd_tx,
        events_rx,
        outgoing_rx,
        incoming_tx,
        decided_channel_capacity: cfg.decided_channel_capacity,
    }

harness.source:
//! Sourced probe: does an event stream that the application does not consume park
//! the single omnipaxos_runtime actor task, and with it the node's whole consensus
//! participation (ticks, incoming messages, Command replies)?
//!
//! The actor publishes every observed transition with `event_tx.send(..).await`
//! (actor.rs `detect_and_emit_events`), awaited inside the tick arm of the only
//! `run` select loop, on the channel `spawn_actor` builds as
//! `async_channel::bounded(RuntimeConfig::event_capacity)`. The receiver always
//! exists: the handle owns one even if the application never calls
//! `subscribe_events()`. The other two egress paths of the same actor use
//! `try_send` instead.
//!
//! Case 1 leaves that receiver unread while the cluster is kept busy, so the bound
//! `event_capacity` is reached. Case 2 is the paired control: same cluster, same
//! capacity, same activity, only difference is a task that drains the events.

use std::{
    collections::HashMap,
    future::Future,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::Duration,
};

use omnipaxos::{
    storage::{Entry, Snapshot},
    util::NodeId,
    ClusterConfig, OmniPaxosConfig, ServerConfig,
};
use omnipaxos_runtime::{
    spawn_actor, AsyncRuntime, OmniPaxosEvent, OmniPaxosHandle, RuntimeConfig,
};
use omnipaxos_storage::memory_storage::MemoryStorage;

/// Small but non-degenerate bound: the probe only needs the bound to be reached
/// inside a bounded window. The mechanism is the same for any finite capacity
/// (default 1024); only the number of unconsumed transitions changes.
const EVENT_CAPACITY: usize = 64;
/// Paced so that consecutive decided-index changes are observed in separate ticks,
/// i.e. each decision produces one event instead of one amalgamated event.
const PROPOSAL_PACE_MS: u64 = 4;

#[derive(Clone, Debug, Default, PartialEq, serde::Serialize, serde::Deserialize)]
struct TestEntry(u64);

#[derive(Clone, Debug, Default, serde::Serialize, serde::Deserialize)]
struct NoSnapshot;

impl Snapshot<TestEntry> for NoSnapshot {
    fn create(_entries: &[TestEntry]) -> Self {
        NoSnapshot
    }
    fn merge(&mut self, _delta: Self) {}
    fn use_snapshots() -> bool {
        false
    }
}

impl Entry for TestEntry {
    type Snapshot = NoSnapshot;
}

/// Minimal executor: tokio (a dev-dependency of this crate) drives the actor task.
struct TestRuntime;

impl AsyncRuntime for TestRuntime {
    type JoinHandle = ();
    fn spawn<F>(future: F)
    where
        F: Future<Output = ()> + Send + 'static,
    {
        let _ = tokio::spawn(future);
    }
    fn sleep(duration: Duration) -> impl Future<Output = ()> + Send + 'static {
        tokio::time::sleep(duration)
    }
}

fn build_op(
    pid: NodeId,
    nodes: Vec<NodeId>,
) -> omnipaxos::OmniPaxos<TestEntry, MemoryStorage<TestEntry>> {
    #[allow(clippy::needless_update)]
    let server_config = ServerConfig {
        pid,
        election_tick_timeout: 3,
        resend_message_tick_timeout: 5,
        buffer_size: 100,
        batch_size: 1,
        flush_batch_tick_timeout: 100,
        leader_priority: 0,
        ..Default::default()
    };
    OmniPaxosConfig {
        cluster_config: ClusterConfig {
            configuration_id: 1,
            nodes,
            flexible_quorum: None,
        },
        server_config,
    }
    .build(MemoryStorage::default())
    .expect("config build")
}

struct Cluster {
    handles: HashMap<NodeId, OmniPaxosHandle<TestEntry>>,
    /// Inspection handles on each node's event stream (clones of the same
    /// per-node receiver), used to read the channel state without consuming it.
    event_rx: HashMap<NodeId, async_channel::Receiver<OmniPaxosEvent>>,
}

/// 3-node in-process cluster: real OmniPaxos instances, real actors, in-memory
/// transport that forwards every outgoing message to its receiver's actor.
///
/// `consumer` decides what the application does with each node's event stream:
/// nothing (the handle's own receiver is simply never read) or drain it in a task.
async fn spawn_cluster(drain_events: bool) -> Cluster {
    let nodes: Vec<NodeId> = vec![1, 2, 3];
    let cfg = RuntimeConfig {
        tick_period: Duration::from_millis(2),
        egress_period: Duration::from_millis(1),
        event_capacity: EVENT_CAPACITY,
        append_notify_timeout: Duration::from_millis(1500),
        ..Default::default()
    };
    let mut handles: HashMap<NodeId, OmniPaxosHandle<TestEntry>> = HashMap::new();
    let mut event_rx = HashMap::new();
    for pid in nodes.clone() {
        let op = build_op(pid, nodes.clone());
        let h = spawn_actor::<TestEntry, MemoryStorage<TestEntry>, TestRuntime>(op, cfg.clone());
        let rx = h.subscribe_events();
        if drain_events {
            tokio::spawn(async move { while rx.recv().await.is_ok() {} });
        }
        event_rx.insert(pid, h.subscribe_events());
        handles.insert(pid, h);
    }
    let arc = Arc::new(handles.clone());
    for pid in nodes {
        let out = arc[&pid].outgoing_messages();
        let peers = arc.clone();
        tokio::spawn(async move {
            while let Ok(msg) = out.recv().await {
                if let Some(peer) = peers.get(&msg.get_receiver()) {
                    peer.handle_incoming(msg).await;
                }
            }
        });
    }
    Cluster { handles, event_rx }
}

/// A command round-trip completes: the actor task is running its select loop.
async fn responds(h: &OmniPaxosHandle<TestEntry>, budget: Duration) -> bool {
    tokio::time::timeout(budget, h.decided_idx()).await.is_ok()
}

async fn wait_for_stable_leader(c: &Cluster) -> Option<NodeId> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    while tokio::time::Instant::now() < deadline {
        for h in c.handles.values() {
            if let Ok(Some((leader, true))) =
                tokio::time::timeout(Duration::from_millis(200), h.current_leader()).await
            {
                return Some(leader);
            }
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    None
}

/// Keep proposing ordinary writes on one origin, spaced out so that each decided
/// index change is observed by the actors in a separate tick.
fn keep_proposing(c: &Cluster, origin: NodeId, from: u64, count: u64) {
    let h = c.handles[&origin].clone();
    tokio::spawn(async move {
        for v in from..from + count {
            let origin_handle = h.clone();
            tokio::spawn(async move {
                let _ = origin_handle.append(TestEntry(v)).await;
            });
            tokio::time::sleep(Duration::from_millis(PROPOSAL_PACE_MS)).await;
        }
    });
}

fn channel_state(c: &Cluster) -> String {
    let mut s = String::new();
    for pid in [1u64, 2, 3] {
        let rx = &c.event_rx[&pid];
        s.push_str(&format!(
            " pid{pid}[len={} capacity={:?} full={} closed={}]",
            rx.len(),
            rx.capacity(),
            rx.is_full(),
            rx.is_closed()
        ));
    }
    s
}

async fn responsive_nodes(c: &Cluster, budget: Duration) -> usize {
    let mut n = 0;
    for h in c.handles.values() {
        if responds(h, budget).await {
            n += 1;
        }
    }
    n
}

/// Case 1: nothing consumes the event stream; the cluster is kept busy until the
/// bound is reached.
#[tokio::test]
async fn unconsumed_event_stream_stops_actor_loop() {
    let c = spawn_cluster(false).await;

    // The application never reads events. Get a leader going first, then keep the
    // cluster observing transitions until the event bound is reached.
    let leader = wait_for_stable_leader(&c).await;
    assert!(
        leader.is_some(),
        "setup: no stable leader while the event channel still had room{}",
        channel_state(&c)
    );
    keep_proposing(&c, leader.unwrap(), 0, EVENT_CAPACITY as u64 * 3);

    // Witness 1: every node reached the bound, so the actor can no longer publish
    // the next transition it observes.
    let deadline = tokio::time::Instant::now() + Duration::from_secs(8);
    loop {
        let full = [1u64, 2, 3]
            .iter()
            .filter(|pid| c.event_rx[pid].is_full() && !c.event_rx[pid].is_closed())
            .count();
        if full == 3 {
            break;
        }
        assert!(
            tokio::time::Instant::now() < deadline,
            "the unconsumed event channels did not reach their bound:{}",
            channel_state(&c)
        );
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    // Witness 2: at least one node's actor loop is parked, and it stays parked
    // (samples over ~2s never show it serving a command again).
    let mut parked_pid: Option<NodeId> = None;
    let mut permanently_parked = true;
    for _ in 0..10 {
        let mut this_sample: Vec<NodeId> = Vec::new();
        for (pid, h) in c.handles.iter() {
            if !responds(h, Duration::from_millis(200)).await {
                this_sample.push(*pid);
            }
        }
        if this_sample.is_empty() {
            permanently_parked = false;
            break;
        }
        parked_pid = Some(parked_pid.map_or(this_sample[0], |p| p));
        tokio::time::sleep(Duration::from_millis(200)).await;
    }
    let parked_pid = parked_pid.expect("no node stopped answering commands");
    assert!(
        permanently_parked,
        "the parked actor recovered by itself; observed channel state:{}",
        channel_state(&c)
    );
    assert!(
        !responds(&c.handles[&parked_pid], Duration::from_millis(500)).await,
        "node {parked_pid} answered again; channel state:{}",
        channel_state(&c)
    );

    // Witness 3: on that parked node the proposal endpoint is gone too - its
    // append_notify_timeout is 1500ms, so a running actor would have answered
    // (Timeout at the latest) well before the outer 4s.
    let h = c.handles[&parked_pid].clone();
    let resolved = tokio::time::timeout(
        Duration::from_secs(4),
        h.append_notify_with_timeout(TestEntry(999), Duration::from_millis(300)),
    )
    .await;
    assert!(
        resolved.is_err(),
        "append_notify on parked node {parked_pid} resolved: {resolved:?}"
    );
}

/// Case 2 (control): same cluster, same capacity, same activity; the only
/// difference is that each node's event stream is drained.
#[tokio::test]
async fn drained_event_stream_keeps_actor_loop_running() {
    let c = spawn_cluster(true).await;
    let leader = wait_for_stable_leader(&c).await;
    assert!(leader.is_some(), "control: no stable leader{}", channel_state(&c));
    let leader = leader.unwrap();
    keep_proposing(&c, leader, 0, EVENT_CAPACITY as u64 * 3);

    let mut alive = 0;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(8);
    while tokio::time::Instant::now() < deadline {
        alive = responsive_nodes(&c, Duration::from_millis(200)).await;
        if alive == c.handles.len() {
            break;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    assert_eq!(
        alive,
        c.handles.len(),
        "control: some actor loop stopped with a drained event stream{}",
        channel_state(&c)
    );

    let follower = *c.handles.keys().find(|&&p| p != leader).unwrap();
    let idx = match tokio::time::timeout(
        Duration::from_secs(5),
        c.handles[&follower].append_notify(TestEntry(7)),
    )
    .await
    {
        Ok(Ok(idx)) => idx,
        other => panic!("control append_notify: expected Ok(idx), got {other:?}"),
    };
    assert!(idx >= 1, "control append_notify returned idx {idx}");
}

